import {
  Directive,
  ElementRef,
  Input,
  OnChanges,
  OnInit,
  Renderer2,
} from '@angular/core';

@Directive({
  selector: '[appVisibility]',
})
export class VisibilityDirective implements OnInit, OnChanges {
  constructor(private el: ElementRef<any>, private rendrer: Renderer2) {}
  @Input() visible: boolean = false;
  ngOnInit(): void {}

  ngOnChanges() {
    if (this.visible) {
      this.rendrer.addClass(this.el.nativeElement, 'visibility-visible');
    } else {
      this.rendrer.addClass(this.el.nativeElement, 'visibility-hidden');
    }
  }
}
