import { Component, Injector, OnInit, ViewEncapsulation } from '@angular/core';
import { LocalStorageKeys } from '@fusionCore/models/enum/LocalStorageKeys.enum';
import { FusionBase } from '@microSharedLib/core/models/classes/FusionBase';
import { AuthService } from '@microSharedLib/services/auth.service';
import { EndOfDayService } from '@microSharedLib/services/end-of-day.service';
import { UntilDestroy, untilDestroyed } from '@ngneat/until-destroy';
import { DynamicDialogRef } from 'primeng/dynamicdialog';
@Component({
  selector: 'micro-finance-close-branch',
  templateUrl: './close-branch.component.html',
  styleUrls: ['./close-branch.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
@UntilDestroy({ checkProperties: true })
export class CloseBranchComponent extends FusionBase implements OnInit {
  currentLanguage: string = '';
  currentSession!:any;
  constructor(
    injector: Injector,
    private serviceQuery: EndOfDayService,
    private dialogRef: DynamicDialogRef,
    private authService:AuthService

  ) {
    super(injector);
    this.messageTranslationPrefix = 'PAGES.CLOSE-BRANCH-PAGE.MESSAGES.';
  }

  ngOnInit(): void {
    this.getAppLanguage();
    this.currentSession = this.authService.getSession();
  }
  override getAppLanguage(): void {
    this.currentLanguage = this.getFusionHelper().getActiveLanguage(
      LocalStorageKeys.APP_LANG
    );
    this.getTranslation()
      .onLangChange.pipe(untilDestroyed(this))
      .subscribe((lang) => {
        this.currentLanguage = lang?.lang;
      });
  }
  closeBranch() {
    this.serviceQuery
      .closeBranch(this.currentSession.brCode)
      .pipe(untilDestroyed(this))
      .subscribe((data) => {
        if(data.statusCode === 200){
          this.closeDialog();
          this.doSignout();
        }
      });
  }
  doSignout() {
    this.authService.setUserLoggedIn(false);
    this.getLocalStorage().removeLocal(LocalStorageKeys.APP_TOKEN_SESSION);
    this.getLocalStorage().removeSession(LocalStorageKeys.APP_TOKEN_SESSION);
    this.getLocalStorage().removeSession(LocalStorageKeys.APP_IS_LOGGED);
    
    this.getRouter().navigate(['/auth/login']);
  }
  closeDialog() {
    this.dialogRef.close({ cancel: true, confirm: false });
  }
}

