import {
  Component,
  Input,
  Output,
  EventEmitter,
  OnInit,
  forwardRef,
} from '@angular/core';
import {
  ControlValueAccessor,
  NG_VALUE_ACCESSOR,
  FormGroup,
  FormControl,
} from '@angular/forms';

@Component({
  selector: 'micro-finance-id-number-component',
  templateUrl: './id-number.component.html',
  styleUrls: ['./id-number.component.scss'],
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => IdNumberComponent),
      multi: true,
    },
  ],
})
export class IdNumberComponent implements OnInit, ControlValueAccessor {
  @Input() min: number = 0;
  @Input() maxlength: number = 14;
  @Input() useGrouping: boolean = false;
  @Input() step: number = 0;
  @Input() validationErrorList: string[] = [];
  @Input() placeholder!: string;
  @Input() formInstance!: FormGroup;
  @Input() controlName!: string;
  @Input() controlNameFullPath!: string;

  @Output() valueChange = new EventEmitter<any>();
  @Output() ngModelChange = new EventEmitter<any>();

  value: any = null; // Model value
  disabled = false;
  oldCustId!: any;
  // Functions to propagate changes
  onChange = (value: any) => {};
  onTouched = () => {};

  ngOnInit(): void {}

  // ControlValueAccessor methods
  writeValue(value: any): void {
    this.value = value;
  }

  registerOnChange(fn: any): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: any): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.disabled = isDisabled;
  }

  // Handle input change
  // onInputChange(event: any): void {
  //   const value = event;

  //   // Example condition: Emit only if the value is even
  //   if (String(value).length == this.maxlength) {
  //     if (value != this.oldCustId) {
  //       this.oldCustId = value;
  //       this.value = value;
  //       this.formInstance.get(this.controlNameFullPath)?.setValue(value);
  //       this.onChange(value); // Notify Angular forms
  //       this.ngModelChange.emit(value); // Emit custom event
  //     }
  //   }
  // }

  onInputChange(event: any): void {
    const value = event;
  
    // If form reset, clear values
    if (!value) {
      this.oldCustId = null;
      this.value = null;
      this.formInstance.get(this.controlNameFullPath)?.setValue(null);
      this.onChange(null);
      this.ngModelChange.emit(null);
      return;
    }
  
    if (String(value).length == this.maxlength) {
      if (value != this.oldCustId) {
        this.oldCustId = value;
        this.value = value;
        this.formInstance.get(this.controlNameFullPath)?.setValue(value);
        this.onChange(value);
        this.ngModelChange.emit(value);
      }
    }
  }
  


  get formGroup() {
    const control = this.formInstance.get(this.controlNameFullPath) as FormControl;
    const parentGroup = control.parent as FormGroup;
    return parentGroup;
  }
  // Enforce maxlength
  limitLength(event: any): void {
    const originalEvent = event.originalEvent; // Native input event
    const inputElement = originalEvent.target; // Access the input element
    let value = inputElement.value;
    if (value.length > this.maxlength) {
      value = value.slice(0, this.maxlength);
      inputElement.value = value; // Update input's visible value
    }
    if (value.length == this.maxlength) {
      this.formInstance.get(this.controlNameFullPath)?.setValue(value);
    }
  }
}
