import {
  Component,
  inject,
  Injector,
  OnDestroy,
  OnInit,
  Renderer2,
  ViewChild,
} from '@angular/core';
import { NavigationEnd, Router } from '@angular/router';
import { filter, Subscription } from 'rxjs';
import { LayoutService } from './service/app.layout.service';
import { AppSidebarComponent } from './app.sidebar.component';
import { UntilDestroy, untilDestroyed } from '@ngneat/until-destroy';
import { FusionBase } from '@microSharedLib/core/models/classes/FusionBase';
import { LocalStorageKeys } from '@fusionCore/models/enum/LocalStorageKeys.enum';
import { ApplicationLookupsService } from '@microSharedLib/services/application-lookups.service';

@Component({
  selector: 'app-layout',
  templateUrl: './app.layout.component.html',
})
@UntilDestroy({ checkProperties: true })
export class AppLayoutComponent
  extends FusionBase
  implements OnInit, OnDestroy {
  overlayMenuOpenSubscription: Subscription;
showAlert = sessionStorage.getItem('showAlert');
  menuOutsideClickListener: any;
message:any
  @ViewChild(AppSidebarComponent) appSidebar!: AppSidebarComponent;
  currentLanguage: string = '';
  isLoginpageActive: boolean = false;
      protected Rout=inject(Router)

  constructor(
    injector: Injector,
    private appLookupsService: ApplicationLookupsService,
    public layoutService: LayoutService,
    public renderer: Renderer2,
  ) {
    super(injector);
    this.overlayMenuOpenSubscription =
      this.layoutService.overlayOpen$.subscribe(() => {
        if (!this.menuOutsideClickListener) {
          this.menuOutsideClickListener = this.renderer.listen(
            'document',
            'click',
            (event) => {
              const isOutsideClicked = !(
                this.appSidebar.el.nativeElement.isSameNode(event.target) ||
                this.appSidebar.el.nativeElement.contains(event.target) ||
                event.target.classList.contains('p-trigger') ||
                event.target.parentNode.classList.contains('p-trigger')
              );

              if (isOutsideClicked) {
                this.layoutService.state.profileSidebarVisible = false;
                this.layoutService.state.overlayMenuActive = false;
                this.layoutService.state.staticMenuMobileActive = false;
                this.layoutService.state.menuHoverActive = false;
                this.getMenuService.reset();
                this.menuOutsideClickListener();
                this.menuOutsideClickListener = null;
                this.unblockBodyScroll();
              } else {
                if (this.layoutService.state.staticMenuMobileActive) {
                  this.blockBodyScroll();
                }
              }
            }
          );
        }
      });

    this.getRouter()
      .events.pipe(filter((event) => event instanceof NavigationEnd))
      .subscribe(() => {
        this.unblockBodyScroll();
      });
  }

  ngOnInit() {
    this.getAppLanguage();

    if (
      this.getActivatedRoute().snapshot.firstChild?.url[0]?.path === 'login'
    ) {
      this.isLoginpageActive = true;
    }
    

    if (!this.showAlert) {
      this.getNotifyPassword()
    }
  }
  getNotifyPassword() {
    this.appLookupsService.getnotifyPassword().pipe(untilDestroyed(this))
      .subscribe((data) => {
         this.message = this.buildMessage(data.result);
        sessionStorage.setItem("showAlert", this.message?.join('\n'))

      })
  }
  buildMessage(items: any[]): string {
    if (!items || items.length === 0) return '';

    const messages = items.map(item =>
      `${item.description} has ${item.status} ${Math.abs(item.remainingDays)} days ago `
    );

    return messages.join('\n');
  }

  getAppLanguage(): void {
    this.currentLanguage = this.getFusionHelper().getActiveLanguage(
      LocalStorageKeys.APP_LANG
    );
    this.getTranslation()
      .onLangChange.pipe(untilDestroyed(this))
      .subscribe((lang) => {
        this.currentLanguage = lang?.lang;
      });
  }

  blockBodyScroll(): void {
    if (document.body.classList) {
      document.body.classList.add('blocked-scroll');
    } else {
      document.body.className += ' blocked-scroll';
    }
  }

  unblockBodyScroll(): void {
    if (document.body.classList) {
      document.body.classList.remove('blocked-scroll');
    } else {
      document.body.className = document.body.className.replace(
        new RegExp(
          '(^|\\b)' + 'blocked-scroll'.split(' ').join('|') + '(\\b|$)',
          'gi'
        ),
        ' '
      );
    }
  }

  get containerClass() {
    return {
      'layout-theme-light': this.layoutService.config.colorScheme === 'light',
      'layout-theme-dark': this.layoutService.config.colorScheme === 'dark',
      'layout-overlay': this.layoutService.config.menuMode === 'overlay',
      'layout-static': this.layoutService.config.menuMode === 'static',
      'layout-slim': this.layoutService.config.menuMode === 'slim',
      'layout-horizontal': this.layoutService.config.menuMode === 'horizontal',
      'layout-static-inactive':
        !this.layoutService.state.staticMenuDesktopInactive &&
        this.layoutService.config.menuMode === 'static',
      'layout-overlay-active': this.layoutService.state.overlayMenuActive,
      'layout-mobile-active': this.layoutService.state.staticMenuMobileActive,
      'p-input-filled': this.layoutService.config.inputStyle === 'filled',
      'p-ripple-disabled': !this.layoutService.config.ripple,
    };
  }

  get containerClassAr() {
    return {
      'layout-theme-light': this.layoutService.config.colorScheme === 'light',
      'layout-theme-dark': this.layoutService.config.colorScheme === 'dark',
      'layout-overlay-ar': this.layoutService.config.menuMode === 'overlay',
      'layout-static-ar': this.layoutService.config.menuMode === 'static',
      'layout-slim': this.layoutService.config.menuMode === 'slim',
      'layout-horizontal': this.layoutService.config.menuMode === 'horizontal',
      'layout-static-inactive':
        !this.layoutService.state.staticMenuDesktopInactive &&
        this.layoutService.config.menuMode === 'static',
      'layout-overlay-active': this.layoutService.state.overlayMenuActive,
      'layout-mobile-active': this.layoutService.state.staticMenuMobileActive,
      'p-input-filled': this.layoutService.config.inputStyle === 'filled',
      'p-ripple-disabled': !this.layoutService.config.ripple,
    };
  }

  ngOnDestroy() {
    if (this.overlayMenuOpenSubscription) {
      this.overlayMenuOpenSubscription.unsubscribe();
    }

    if (this.menuOutsideClickListener) {
      this.menuOutsideClickListener();
    }
  }
}
