import { Component, OnInit, Injector } from '@angular/core';
import { UntilDestroy, untilDestroyed } from '@ngneat/until-destroy';
import { PrimeNGConfig } from 'primeng/api';
import { FusionBase } from '@microSharedLib/core/models/classes/FusionBase';
import { LocalStorageKeys } from '@fusionCore/models/enum/LocalStorageKeys.enum';
import { AuthService } from '@microSharedLib/services/auth.service';
import { ApplicationSettingsService } from '@microSharedLib/services/application-settings.service';
import { ApplicationLookupsService } from '@microSharedLib/services/application-lookups.service';
import { FusionTreeMenuModel } from '@microSharedLib/core/models/enum/FusionModuleScreens.model';
import { NavigationStart } from '@angular/router';
import { LayoutService } from '@fusionLayout/service/app.layout.service';
@Component({
  selector: 'fusion-root',
  templateUrl: './app.component.html',
})
@UntilDestroy({ checkProperties: true })
export class AppComponent extends FusionBase implements OnInit {
  currentLanguage: string = '';
  isSocketConnected: boolean = false;
  intTimer!: any;
  constructor(
    injector: Injector,
    private primengConfig: PrimeNGConfig,
    private authService: AuthService,
    private lookupService: ApplicationLookupsService,
    public layoutService: LayoutService
  ) {
    super(injector);
  }

  ngOnInit() {
    this.getAppLanguage();
    this.setAppLanguageConfig();
    this.checkUserloggedInOnStart();
    this.getRolesPermissionData();
    this.primengConfig.ripple = true;
    document.documentElement.style.fontSize = '14px';

    // this.intTimer = setInterval(() => {
    //   if (this.isSocketConnected) {
    //     console.log('socket connece and i will get data after 2 second');
    //     this.socketService.getNotificationFromServer({
    //       userid: 1,
    //       message: 'give me data',
    //     });
    //   } else {
    //     console.log('i will clear');
    //     window.clearInterval(this.intTimer);
    //   }
    // }, 5000);
  }

  getAppLanguage(): void {
    this.currentLanguage = this.getFusionHelper().getActiveLanguage(
      LocalStorageKeys.APP_LANG
    );
    this.getTranslation()
      .onLangChange.pipe(untilDestroyed(this))
      .subscribe((lang) => {
        this.currentLanguage = lang?.lang;
      });
  }

  getRolesPermissionData() {
    const rolesPerm: FusionTreeMenuModel = this.getLocalStorage().getSessionStorage(
      LocalStorageKeys.APP_TREE
    );
    if (rolesPerm) {
      const moduleSbmoduleList = rolesPerm.modulesSubmodule;
      const screensList = rolesPerm.screens;
      this.getpermissionService().flushPermissions();

      this.getMenuService.setModuleScreenPermission(rolesPerm);
      // must add this line of code by take the screen from the response
      this.getpermissionService().addPermission([...moduleSbmoduleList, ...screensList]);
    }

    this.getRouter().events.subscribe((ev) => {
      if (ev instanceof NavigationStart) {
        this.repopulatePermissionRoles();
      }
      // if (ev instanceof GuardsCheckEnd) {
      //   this.repopulatePermissionRoles();
      // }
    });
  }

  /** application language config */
  async setAppLanguageConfig() {
    let setting = await ApplicationSettingsService.getSettingsModel;
    this.currentLanguage = this.getLocalStorage()?.getLocal(LocalStorageKeys.APP_LANG)
      ? this.getLocalStorage().getLocal(LocalStorageKeys.APP_LANG)
      : 'ar';

    this.localStorageService.setLocal(
      LocalStorageKeys.APP_LANG,
      (setting.defaultLanguage as string) ?? this.currentLanguage
    );
    this.getTranslation().use(
      this.currentLanguage ?? (setting.defaultLanguage as string)
    );
    this.getTranslation().setDefaultLang(
      this.currentLanguage ?? (setting.defaultLanguage as string)
    );
    this.getTranslation().onLangChange.subscribe((lang) => {
      this.changePageDirection(lang?.lang);
      this.localStorageService.setLocal(LocalStorageKeys.APP_LANG, lang?.lang);
    });
  }

  /**
   * @description change font when app start up or language change
   */
  changePageDirection(lang: string) {
    if (lang === 'ar') {
      // this line to change the dire of the index page
      this.getDocument()!.getElementById('htmlParentItem')!.setAttribute('dir', 'rtl');
      // this line to change the language
      this.getDocument()!.getElementById('htmlParentItem')!.setAttribute('lang', 'ar');
      this.getDocument()!
        .getElementById('theme-css')!
        .setAttribute('href', 'assets/layout/styles/theme/lara-light-blue/theme-rtl.css');
      // << change font when language arabic to be 'BahijTheSansRegular' >> //
      // this.getDocument()!.getElementById('appRootBody')!.style.fontFamily =
      //   'Cairo sans-serif !important';
    } else {
      // << change font when language arabic to be 'Montserrat' >> //
      // this line to change the dire of the [index page]
      this.getDocument()!.getElementById('htmlParentItem')!.setAttribute('dir', 'ltr');
      // this line to change the language
      this.getDocument()!.getElementById('htmlParentItem')!.setAttribute('lang', 'en-US');
      this.getDocument()!
        .getElementById('theme-css')!
        .setAttribute('href', 'assets/layout/styles/theme/lara-light-blue/theme.css');
      // this.getDocument()!.getElementById('appRootBody')!.style.fontFamily =
      //   'Cairo, sans-serif';
    }
  }

  async checkUserloggedInOnStart() {
    const localData = this.localStorageService.getLocal(LocalStorageKeys.APP_IS_LOGGED);
    const sessionData = this.localStorageService.getSessionStorage(
      LocalStorageKeys.APP_IS_LOGGED
    );
    let treeData = this.localStorageService.getSessionStorage(LocalStorageKeys.APP_TREE);

    if (this.authService.isTokenExpired()) {
      this.getAlertToaster().showToastWarn('', 'Current user token is expired');
      this.getRouter().navigate(['auth/login']);
      return;
    }

    if (!localData && !sessionData) {
      this.getRouter().navigate(['auth/login']);
    } else {
      this.lookupService.setTreeMenudata(treeData);
      // this.getRouter().navigate(['/dashboard']);
      this.authService.setUserLoggedIn(true);
    }
  }
}
