import { Component, Input, Output, EventEmitter, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, FormArray, Validators } from '@angular/forms';
import { ImageUtil } from '@microSharedLib/shared/utils/ImageUtil';
import { ToasterService } from '@microSharedLib/core/helpers/Toaster.service';
@Component({
  selector: 'micro-finance-upload-component',
  templateUrl: './upload.component.html',
  styleUrls: ['./upload.component.scss']
})
export class UploadComponent implements OnInit {
  @Input() formArrayName: string = 'documents';
  @Input() parentForm!: FormGroup;
  @Input() messageTranslationPrefix: string = '';
  @Input() maxArrayLength: number = 10;
  @Input() fixedArrayLength!: number;
  @Output() fileUpload = new EventEmitter<{ event: Event, index: number }>();

  constructor(private fb: FormBuilder, private ToasterService: ToasterService) { }

  ngOnInit() {
    if (!this.parentForm.get(this.formArrayName)) {
      this.parentForm.setControl(this.formArrayName, this.fb.array([]));
    }
    this.initializeFormArray();
  }

  get formArray(): FormArray {
    return this.parentForm.get(this.formArrayName) as FormArray;
  }
  initializeFormArray() {
    if (this.fixedArrayLength) {
      for (let i = this.formArray.length; i < this.fixedArrayLength; i++) {
        this.addDataArrayItem();
      }
    }
  }

  addDataArrayItem() {
    const item = this.fb.group({
      notes: [null, Validators.required],
      fileContentType: [null],
      fileName: [null],
      fileContent: [null],
    });
    this.formArray.push(item);
  }

  removeDataArrayItem(index: number) {
    this.formArray.removeAt(index);
  }

  clearDataArrayItem() {
    this.formArray.clear();
  }

  async onUploadFile(event: any, index: number) {
    if (!event.target) return;
    const file = event.target?.files[0];
    const fileName = file.name;
    const indexdot = fileName.split('.');
    if (file.type !== 'application/pdf' || indexdot.length > 2) {
      this.ToasterService.showToastWarn('', 'برجاء تحميل ملف pdf');
      return;
    }
    const reader: FileReader = new FileReader();
    reader.readAsBinaryString(file);

    reader.onload = async (e: any) => {
      const content = reader.result as string;
        const isImageOnlyPDF = content.includes('/Subtype /Image') || content.includes('Subtype/Image');

      if (isImageOnlyPDF) {
        this.uploadFileData(event,index, file)
      }
      else{
  const suspiciousKeywords = [
        '/JavaScript',
        '/JS',
        '/AA',
        '/OpenAction',
        'Launch',
        '<script',
      ];

      const isSuspicious = suspiciousKeywords.some(keyword =>
        content.includes(keyword)
      );
      if (isSuspicious) {
        this.ToasterService.showToastWarn('',
 '❌ الملف مرفوض بالرجاء رفع ملف اخر'        );
        return;
      }
       else {
               this.uploadFileData(event,index, file)

      }
      }
    
     
    }
  }
  async uploadFileData(event:any,index:number, file:any){
     const control = this.formArray.at(index);
        let filebase64 = await ImageUtil.convertBlobToBase64(file);
        control.patchValue({ fileContentType: file.type, fileName: file.name, fileContent: filebase64, });

  }

}
