import { HttpContext, HttpContextToken } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { FusionServers } from '@microSharedLib/core/models/enum/FusionServers.enum';
import { HttpResponseModel } from '@microSharedLib/core/models/interfaace/HttpResponseModel.interface';
import { IS_SPINNER_ENABLED } from '@microSharedLib/core/token/AnbHttpToken';
import { HttpCall } from '@microSharedLib/services/http/HttpCall.service';
import { NgxSpinnerService } from 'ngx-spinner';
import { tap } from 'rxjs';

@Injectable({
  providedIn: 'root',
})
export class EndOfDayService {
  constructor(private http: HttpCall, private spinnerService: NgxSpinnerService) {}
  getInfo() {
    return this.http.getAll<HttpResponseModel>(
      FusionServers.BASE_API_SERVER,
      `adminController/eod/getInfo`
    );
  }

  closeAllBranches(queryData?: any) {
    return this.http.post<HttpResponseModel>(
      FusionServers.BASE_API_SERVER,
      `adminController/eod/closeAllBranches`,
      queryData ? { ...queryData } : {}
    );
  }
   openAllBranches(queryData?: any) {
    return this.http.post<HttpResponseModel>(
      FusionServers.BASE_API_SERVER,
      `adminController/eod/openAllBranches`,
      queryData ? { ...queryData } : {}
    );
  }
  runProcess(queryData?: any) {
    return this.http.post<HttpResponseModel>(
      FusionServers.BASE_API_SERVER,
      `adminController/eod/runProcess`,
      queryData ? { ...queryData } : {}
    );
  }
  getStatus(queryData?: any) {
    return this.http.getAll<HttpResponseModel>(
      FusionServers.BASE_API_SERVER,
      `adminController/eod/getStatus`,
      queryData ? { ...queryData } : {},
      new HttpContext().set(IS_SPINNER_ENABLED, false)
    );
  }
  //calendar page
  getAllCalendar(country: number, month: number, year: number) {
    return this.http.getAll<HttpResponseModel>(
      FusionServers.BASE_API_SERVER,
      `adminController/calendar/getAllAdminCalendar?country=${country}&month=${month}&year=${year}`
    );
  }

  updateCalendarData(data: any) {
    return this.http.update<HttpResponseModel>(
      FusionServers.BASE_API_SERVER,
      `adminController/calendar/updateCalendar`,
      data
    );
  }
  closeBranch(brcode: any) {
    return this.http.post<HttpResponseModel>(
      FusionServers.BASE_API_SERVER,
      'adminController/eod/closeBranch',
      { brcode }
    );
  }
  getAllCashBoxByusernoAndBrcode(usrno: any, brcode: any) {
    return this.http.getAll<HttpResponseModel>(
      FusionServers.BASE_API_SERVER,
      `finance/glCashDef/getAllCashBoxById?usrNo=${usrno}&brCode=${brcode}`
    );
  }
  saveBranchCashCount(data: any) {
    return this.http.post<HttpResponseModel>(
      FusionServers.BASE_API_SERVER,
      `finance/glBrCashCount`,
      data
    );
  }
  //calendar page
}
