import { Pipe, PipeTransform } from '@angular/core';

@Pipe({
  name: 'filter',
})
export class FilterPipe implements PipeTransform {
  transform(
    value: any[],
    searchText: string,
    objectProp: string = 'name',
    lang: string = 'en'
  ): any {
    if (!value || !searchText) {
      return value;
    }

    return value.filter((text: any) => {
      return text[objectProp][lang]
        ?.toLowerCase()
        .includes(searchText.toLowerCase());
    });
  }
}
