import { Inject, Injectable } from '@angular/core';
import {
  HttpInterceptor,
  HttpRequest,
  HttpHandler,
  HttpEvent,
  HttpErrorResponse,
} from '@angular/common/http';
import { Observable, throwError } from 'rxjs';
import { catchError } from 'rxjs/operators';
import { HttpErrorMessage } from './HttpErrorMessage';
import { TranslateService } from '@ngx-translate/core';
import { Router } from '@angular/router';
import { ToasterService } from '@microSharedLib/core/helpers/Toaster.service';
import { FusionApps } from '@microSharedLib/core/models/enum/FusionApps.enum';
import { AuthService } from '@microSharedLib/services/auth.service';
import { LocalStorageService } from '@microSharedLib/core/helpers/LocalStorage.service';
import { LocalStorageKeys } from '@fusionCore/models/enum/LocalStorageKeys.enum';
@Injectable({
  providedIn: 'root',
})
export class ErrorhandlerService implements HttpInterceptor {
  constructor(
    private router: Router,
    private translate: TranslateService,
    private notify: ToasterService,
    private authService: AuthService,
    private localStorageService: LocalStorageService,
    @Inject('appName') private appName: string
  ) { }

  HttpErrorMsg: HttpErrorMessage = new HttpErrorMessage(this.router, this.appName);

  intercept(req: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
    return next.handle(req).pipe(
      catchError((err: HttpErrorResponse) => {
        let trans = Object.values(
          this.translate.instant([
            `COMMON-MESSAGES.HTTP-STATUS.401`,
            `COMMON-MESSAGES.Error`,
          ])
        ) as string[];
        if (req.url.includes('/login') && err.status === 307) {
          this.router.navigate(['/auth/changePassword']);
        }
        if (err.status === 401) {
          this.localStorageService.removeLocal(LocalStorageKeys.APP_TOKEN_SESSION);
          this.localStorageService.removeSession(LocalStorageKeys.APP_TOKEN_SESSION);
          this.localStorageService.removeSession(LocalStorageKeys.APP_IS_LOGGED);
          this.authService.setUserLoggedIn(false);
          this.notify.showToastError('', `${trans[0]}`);
          if (err.error.errors) {
            (err.error.errors as any[]).forEach((ele) => {
              this.notify.showToastError('', ele.msg);
            });
            this.router.navigate(['/auth/login']);
          } else {
            this.notify.showToastError('', err.error.status);
          }
        } else if (err.status === 409) {
          if (err.error && err.error.messages) {
            this.notify.showToastError(err.error.status, err.error.messages[0]);
          }
          if (err.error && err.error.errors && err.error.errors.length > 0) {
            let messages = '';
            for (let i = 0; i < err.error.errors.length; i++) {
              messages += err.error.errors[i] + '<br />';
            }
            if (messages && messages != '') {
              this.notify.showToastError('', messages);
            }
          }
        } 
        else if(err.status === 429){
          this.notify.showToastError(err.error.status,err.error.errors[0].msg);
        }
        else if (err.status === 400) {
          if (err.error && err.error.errors) {
            for (let i = 0; i < err.error.errors.length; i++) {
              if (err.error.errors[i]) {
                this.notify.showToastError(
                  this.Locz('COMMON-MESSAGES.Error'),
                  err.error.errors[i].msg
                );
              }
            }
          }
        } else if (err.status === 404) {
          this.notify.showToastError(
            this.Locz('COMMON-MESSAGES.Error'),
            this.Locz('COMMON-MESSAGES.PageNotFoundErrorMessage')
          );
        } else if (err.status === 500) {
          this.notify.showToastError(
            this.Locz('COMMON-MESSAGES.Error'),
            this.Locz('COMMON-MESSAGES.InternalServerErrorMessage')
          );
          // this.router.navigate(['/auth/login']);
          this.router.navigate(['/pages/server-error']);
        } else if (err.status === 504) {
          this.notify.showToastError(
            this.Locz('Error'),
            this.Locz('COMMON-MESSAGES.NetworkErrorMessage')
          );
        }
        // << check client side error >> //
        if (err.error instanceof ErrorEvent) {
          throwError(err);
        } else {
          if (err.statusText === 'Unknown Error') {
            // this.HttpErrorMsg.handleHttpErrors(err.statusText);
            this.notify.showToastError('', 'COMMOM-MESSAGES.Error');
            this.router.navigate(['/pages/server-error']);
          } else {
            // this.HttpErrorMsg.handleHttpErrors(err.status);
          }
        }
        return throwError(err);
      })
    );
  }

  Locz(key: string) {
    return this.translate.instant(key);
  }
}
