import { Component, Injector, Input, OnInit } from '@angular/core';
import { LocalStorageKeys } from '@fusionCore/models/enum/LocalStorageKeys.enum';
import { FusionBase } from '@microSharedLib/core/models/classes/FusionBase';
import { LoginResponseModel } from '@microSharedLib/core/models/interfaace/AppAuthEntity.interface';
import { UntilDestroy, untilDestroyed } from '@ngneat/until-destroy';
import { DynamicDialogRef } from 'primeng/dynamicdialog';
import { GenericObject } from './dynamic-popup-readonly.interface';

@Component({
  selector: 'micro-finance-dynamic-popup-readonly',
  templateUrl: './dynamic-popup-readonly.component.html',
  styleUrls: ['./dynamic-popup-readonly.component.scss'],
})
@UntilDestroy({ checkProperties: true })
export class DynamicPopUpReadOnlyComponent<T> extends FusionBase implements OnInit {
  currentLanguage: string = '';
  userSession!: LoginResponseModel;
  activeIndex: number = 0;
  @Input() messagePrefix!:string;
  @Input() queryObj!: GenericObject<T>;
  @Input() isTabs: boolean=true;

  constructor(injector: Injector, private dialogRef: DynamicDialogRef) {
    super(injector);
  }

  ngOnInit(): void {
    this.userSession = this.localStorageService.getSessionStorage(
      LocalStorageKeys.APP_TOKEN_SESSION as string
    );
    this.messageTranslationPrefix = this.messagePrefix;
    this.getAppLanguage();
  }
  getAppLanguage(): void {
    this.currentLanguage = this.getFusionHelper().getActiveLanguage(
      LocalStorageKeys.APP_LANG
    );
    this.getTranslation()
      .onLangChange.pipe(untilDestroyed(this))
      .subscribe((lang) => {
        this.currentLanguage = lang?.lang;
      });
  }
  closeModal() {
    this.dialogRef.close({ cancel: true, confirm: false });
  }
}
