import { Injectable } from '@angular/core';
import { FusionServers } from '@microSharedLib/core/models/enum/FusionServers.enum';
import { HttpResponseModel } from '@microSharedLib/core/models/interfaace/HttpResponseModel.interface';
import { SettingModel } from '@microSharedLib/core/models/interfaace/SettingModel.interface';
import { HttpCall } from '@microSharedLib/services/http/HttpCall.service';
import { lastValueFrom } from 'rxjs';
@Injectable({
  providedIn: 'root',
})
export class ApplicationSettingsService {
  public static appSettings: SettingModel;

  constructor(private http: HttpCall) {}

  /** @description get setting promis, allow user to use await to load setting firsrt and then use it
   * for best usability instead of observable and subscription
   * @returns Promise<SettingModel>
   */
  static get getSettingsModel(): Promise<SettingModel> {
    let settingPro = new Promise<any>((resolve, reject) => {
      resolve(ApplicationSettingsService.appSettings);
    });

    return settingPro;
  }

  /** call this function when app start */
  loadSettingData() {
    let settingObs$ = this.http.getAll<HttpResponseModel>(
      FusionServers.BASE_API_SERVER,
      `public/sysUserParameters`
    );
    return lastValueFrom(settingObs$);
  }

  /** @description set setting data in the static variable */
  setSetting(data: any) {
    ApplicationSettingsService.appSettings = { ...data };
  }

  private convertSettingArrayToMap(data: any) {
    let objKeys = Object.keys(data);
    let toMapData = data.map((ele: any, idx: number) => {
      let item = { [data[idx].key]: ele };
      return item;
    });
  }
}
