import {
  Component,
  HostListener,
  Inject,
  Injector,
  Input,
  OnInit,
} from '@angular/core';
import { FusionBase } from '@microSharedLib/core/models/classes/FusionBase';
import { LocalStorageKeysModel } from '@microSharedLib/core/models/interfaace/LocalStorageKeysModel.interface';
import { UntilDestroy, untilDestroyed } from '@ngneat/until-destroy';

@Component({
  selector: 'exceed-saloon-table-menu-actions',
  templateUrl: './table-menu-actions.component.html',
  styleUrls: ['./table-menu-actions.component.scss'],
})
@UntilDestroy({ checkProperties: true })
export class TableMenuActionsComponent extends FusionBase implements OnInit {
  openActions: boolean = false;
  @Input('itemId') itemId!: any;
  currentLanguage: string = '';
  constructor(
    injector: Injector,
    @Inject('localStorageKeys') public localStorage: LocalStorageKeysModel
  ) {
    super(injector);
    this.messageTranslationPrefix = '';
  }

  ngOnInit(): void {
    this.getAppLanguage();
  }

  @HostListener('document:click', ['$event'])
  onClick(event: Event) {
    if (!this.openActions) {
      this.openActions = false;
      this.getDocument()
        .getElementById(`tableMenuId${this.itemId}`)
        ?.classList.remove('table-action__menu--open');
    }
    this.openActions = false;
  }

  getAppLanguage(): void {
    this.currentLanguage = this.getFusionHelper().getActiveLanguage(
      this.localStorage.APP_LANG as string
    );
    this.getTranslation()
      .onLangChange.pipe(untilDestroyed(this))
      .subscribe((lang) => {
        this.currentLanguage = lang?.lang;
      });
  }

  showAction() {
    if (!this.openActions) {
      this.openActions = true;
      this.getDocument()
        .getElementById(`tableMenuId${this.itemId}`)
        ?.classList.add('table-action__menu--open');
    } else {
      this.openActions = false;
      this.getDocument()
        .getElementById(`tableMenuId${this.itemId}`)
        ?.classList.remove('table-action__menu--open');
    }
  }
}
