import { Component, Injector } from '@angular/core';
import { LocalStorageKeys } from '@fusionCore/models/enum/LocalStorageKeys.enum';
import { FusionBase } from '@microSharedLib/core/models/classes/FusionBase';
import { AuthService } from '@microSharedLib/services/auth.service';
import { UntilDestroy, untilDestroyed } from '@ngneat/until-destroy';
import { MenuItem } from 'primeng/api';
import { Observable, lastValueFrom } from 'rxjs';
import { LayoutService } from './service/app.layout.service';
import { fadeOutUpOnLeaveAnimation, fadeInOnEnterAnimation } from 'angular-animations';
import { ApplicationLookupsService } from '@microSharedLib/services/application-lookups.service';
@Component({
  selector: 'app-topbar',
  templateUrl: './app.topbar.component.html',
  animations: [
    fadeOutUpOnLeaveAnimation({ duration: 300, delay: 40 }),
    fadeInOnEnterAnimation({ duration: 350, delay: 40 }),
  ],
})
@UntilDestroy({ checkProperties: true })
export class AppTopBarComponent extends FusionBase {
  isLoggedin$!: Observable<boolean>;
  showHeaderNotification: boolean = false;
  showHeaderWidget: boolean = false;
  ProfileItems: MenuItem[] = [
    {
      id: 'HEADER-PROFILE-TEXT',
      label: '',
      icon: 'pi pi-user mx-1',
      routerLink: '/auth/user-profile',
    },
    // { id: 'HEADER-SETTING-TEXT', label: '', icon: 'pi pi-cog mx-1' },
    { id: 'HEADER-LANGUAGE-TEXT', label: '', icon: 'pi pi-globe mx-1' },
    { separator: true },
    {
      id: 'HEADER-FULLSCREEN-MODE-NAME',
      label: '',
      icon: 'pi pi-window-maximize mx-1',
      command: () => {
        this.getFusionHelper().fullScreenMode();
      },
    },
    { separator: true },
    {
      id: 'HEADER-SIGNOUT-TEXT',
      label: '',
      icon: 'pi pi-sign-out mx-1',
      command: () => {
        this.doSignout();
      },
    },
  ];
  notificationCount: any = 0;
  currentLanguage: string = '';
  todayDate = new Date();
  availableRolesList: any = [];
  selectedRole!: any;
  currentSession!: any;
  constructor(
    injector: Injector,
    public layoutService: LayoutService,
    private authService: AuthService,
    private lookupService: ApplicationLookupsService
  ) {
    super(injector);
    this.messageTranslationPrefix = 'LAYOUT.HEADER.';
  }

  ngOnInit(): void {
    this.getAppLanguage();
    this.currentSession = this.authService.getSession();
    this.translateHeaderMenuItems(this.ProfileItems);
    this.getScreenPermissionOnStart();
    this.isLoggedin$ = this.authService.isUserLoggedIn();
    this.availableRolesList = this.authService.getSession().availableRoleAndScreens;
    this.authService
      .getSelectedRole()
      .pipe(untilDestroyed(this))
      .subscribe((data) => {
        let seletedRole = this.localStorageService.getSessionStorage(
          LocalStorageKeys.APP_USER_SELECTED_ROLE
        );
        if (data) {
          this.selectedRole = data;
        } else {
          this.selectedRole = seletedRole;
        }
      });
  }

  getAppLanguage(): void {
    this.currentLanguage = this.getFusionHelper().getActiveLanguage(
      LocalStorageKeys.APP_LANG
    );
    this.getTranslation()
      .onLangChange.pipe(untilDestroyed(this))
      .subscribe((lang) => {
        this.currentLanguage = lang?.lang;
        this.translateHeaderMenuItems(this.ProfileItems);
      });
  }

  changeLanguage(lang: string) {
    this.getFusionHelper().changeAppDefaultLanguage(LocalStorageKeys.APP_LANG, lang);
  }

  translateHeaderMenuItems(childeren: MenuItem[]) {
    for (let item of childeren) {
      if (item.separator) continue;
      item.label = this.getTranslation().instant(
        `${this.messageTranslationPrefix}${item.id}`
      );
      if (item.items) {
        this.translateHeaderMenuItems(item.items);
      }
    }
    this.ProfileItems = [...childeren];
  }

  doSignout() {
    this.authService
      .signout()
      .pipe(untilDestroyed(this))
      .subscribe((data) => {
        this.authService.setUserLoggedIn(false);
        this.getLocalStorage().removeLocal(LocalStorageKeys.APP_TOKEN_SESSION);
        this.getLocalStorage().removeSession(LocalStorageKeys.APP_TOKEN_SESSION);
        this.getLocalStorage().removeSession(LocalStorageKeys.APP_IS_LOGGED);
        this.getLocalStorage().removeSession(LocalStorageKeys.APP_TREE);
        this.getLocalStorage().removeSession(LocalStorageKeys.APP_USER_ROLES_PERMISSION);
        this.getLocalStorage().removeSession(LocalStorageKeys.APP_USER_SELECTED_ROLE);
        sessionStorage.removeItem("role")
        sessionStorage.removeItem("userno")
        sessionStorage.removeItem("showAlert")

        this.getRouter().navigate(['/auth/login']);
      });
  }

  async onRoleChange(e: any) {
    const role = e.value;

    if (!role) {
      console.error('Role value is undefined or invalid.');
      return;
    }

    try {
      const response = await this.lookupService.getTreeOfPages(role);
      this.localStorageService.setSessionStorage(
        LocalStorageKeys.APP_USER_SELECTED_ROLE,
        role
      );
      this.authService.setSelectedRole(role);

      // Fetch Tree
      const roleData = this.availableRolesList.find((res) => res.roleId === role);
      if (!roleData || !roleData.treeResponse) {
        throw new Error('Tree response not found for the selected role.');
      }
      const treeData = roleData.treeResponse;

      this.getMenuService.setModuleScreenPermission(treeData);

      const moduleSubmoduleList = treeData.modulesSubmodule || [];
      const screensList = treeData.screens || [];
      this.getpermissionService().addPermission([...moduleSubmoduleList, ...screensList]);

      this.lookupService.setTreeMenudata(treeData);
      this.localStorageService.setSessionStorage(LocalStorageKeys.APP_TREE, treeData);

      // Navigate to home or dashboard and reload
      this.getRouter()
        .navigate(['/dashboard'])
        .then(() => {
          window.location.reload();
        });
    } catch (error) {
      console.error('An error occurred during role change:', error.message);
      // Optionally display an error notification to the user
    }
  }

  showHideHeaderNotificataion() {
    this.showHeaderNotification = !this.showHeaderNotification;
    if (this.showHeaderWidget) {
      this.showHeaderWidget = false;
    }
  }

  showHideHeaderWidget() {
    this.showHeaderWidget = !this.showHeaderWidget;
    if (this.showHeaderNotification) {
      this.showHeaderNotification = false;
    }
  }
}
