import { APP_INITIALIZER, NgModule } from '@angular/core';
import { CommonModule, HashLocationStrategy, LocationStrategy } from '@angular/common';
import { AppComponent } from './app.component';
import { AppRoutingModule } from './app-routing.module';
import { AppLayoutModule } from './layout/app.layout.module';
import { ConfirmationService, MessageService } from 'primeng/api';
import { BrowserAnimationsModule } from '@angular/platform-browser/animations';
import { BrowserModule } from '@angular/platform-browser';
import { NotfoundComponent } from './pages/ErrorPages/notfound/notfound.component';
import {
  DialogService,
  DynamicDialogConfig,
  DynamicDialogRef,
} from 'primeng/dynamicdialog';
import { ApplicationSettingsService } from '@microSharedLib/services/application-settings.service';
import { environment } from '../environments/environment';
import { FusionApps } from '@microSharedLib/core/models/enum/FusionApps.enum';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { NgxPermissionsModule } from 'ngx-permissions';
import { TranslateLoader, TranslateModule } from '@ngx-translate/core';
import { TranslateHttpLoader } from '@ngx-translate/http-loader';
import { HttpClient, HttpClientModule, HTTP_INTERCEPTORS } from '@angular/common/http';
import { NgxSpinnerModule } from 'ngx-spinner';
import { LocalStorageKeys } from '@fusionCore/models/enum/LocalStorageKeys.enum';
import { ErrorhandlerService } from '@microSharedLib/core/interceptors/global-error-handler/errorhandler.service';
import { MessageInterceptor } from '@microSharedLib/core/interceptors/global-error-handler/httpMessages.service';
import { RouterLoaderService } from '@microSharedLib/core/interceptors/router-loader.service';
import { HttpLoadingService } from '@microSharedLib/core/interceptors/HttpLoading.service';
import { HeaderKeysService } from '@microSharedLib/core/interceptors/header-keys.service';
import { ToastModule } from 'primeng/toast';
import { DirectivesModule } from '@microSharedLib/shared/directives/DirectivesModule.module';
import { TitleTranslationStrategyService } from '@microSharedLib/core/interceptors/title-translation-strategy.service';
import { SocketIoModule, SocketIoConfig } from 'ngx-socket-io';
import { TitleStrategy } from '@angular/router';
const config: SocketIoConfig = {
  url: environment.socketServer.url,
  options: {
    reconnectionAttempts: 3,
    reconnectionDelay: 2000,
    timeout: 5000,
    reconnection: false,
  },
};

@NgModule({
  declarations: [AppComponent, NotfoundComponent],
  imports: [
    CommonModule,
    BrowserAnimationsModule,
    BrowserModule,
    AppRoutingModule,
    AppLayoutModule,
    HttpClientModule,
    FormsModule,
    ReactiveFormsModule,
    NgxPermissionsModule.forRoot(),
    TranslateModule.forRoot({
      loader: {
        provide: TranslateLoader,
        useFactory: HttpLoaderFactory,
        deps: [HttpClient],
      },
    }),
    DirectivesModule,
    NgxSpinnerModule,
    ToastModule,
    SocketIoModule.forRoot(config),
  ],
  providers: [
    MessageService,
    ConfirmationService,
    DialogService,
    DynamicDialogRef,
    DynamicDialogConfig,
    { provide: LocationStrategy, useClass: HashLocationStrategy },
    {
      provide: HTTP_INTERCEPTORS,
      useClass: ErrorhandlerService,
      multi: true,
    },
    {
      provide: HTTP_INTERCEPTORS,
      useClass: MessageInterceptor,
      multi: true,
    },
    {
      provide: HTTP_INTERCEPTORS,
      useClass: HeaderKeysService,
      multi: true,
    },
    {
      provide: HTTP_INTERCEPTORS,
      useClass: HttpLoadingService,
      multi: true,
    },
    {
      provide: HTTP_INTERCEPTORS,
      useClass: RouterLoaderService,
      multi: true,
    },
    {
      provide: APP_INITIALIZER,
      useFactory: initializeSettingData,
      deps: [ApplicationSettingsService],
      multi: true,
    },
    {
      provide: TitleStrategy,
      useClass: TitleTranslationStrategyService,
    },
    {
      provide: 'env',
      useValue: environment,
    },
    {
      provide: 'appName',
      useValue: FusionApps.FUSION_APP,
    },
    {
      provide: 'localStorageKeys',
      useValue: LocalStorageKeys,
    },
    // { provide: APP_BASE_HREF, useValue: 'http://localhost:5000/#/' },
  ],
  bootstrap: [AppComponent],
})
export class AppModule {}

function initializeSettingData(settingConfig: ApplicationSettingsService) {
  return (): Promise<any> => {
    return settingConfig
      .loadSettingData()
      .then((data) => {
         const dataAll= this.encryptSev.decryptObject(data.result);
    
        settingConfig.setSetting(dataAll);
      })
      .catch((err) => {
        settingConfig.setSetting({});
      });
  };
}

export function HttpLoaderFactory(http: HttpClient): TranslateHttpLoader {
  return new TranslateHttpLoader(http, './assets/i18n/', '.json');
}
