import { Inject, Injectable } from '@angular/core';
import { LocalStorageService } from '@microSharedLib/core/helpers/LocalStorage.service';
import { FusionServers } from '@microSharedLib/core/models/enum/FusionServers.enum';
import {
  LoginModel,
  VerifyOtpModel,
} from '@microSharedLib/core/models/interfaace/AppAuthEntity.interface';
import { JwtHelperService } from '@auth0/angular-jwt';
import { HttpResponseModel } from '@microSharedLib/core/models/interfaace/HttpResponseModel.interface';
import { LocalStorageKeysModel } from '@microSharedLib/core/models/interfaace/LocalStorageKeysModel.interface';
import { BehaviorSubject, lastValueFrom, Observable } from 'rxjs';
import { HttpCall } from './http/HttpCall.service';

@Injectable({
  providedIn: 'root',
})
export class AuthService {
  jwtHelper = new JwtHelperService();

  private isLoggedIn: BehaviorSubject<boolean> = new BehaviorSubject<boolean>(false);

  private selectedRole: BehaviorSubject<any> = new BehaviorSubject<any>(null);

  private baseUrl = 'fmc/auth';
  private baseUrl2 = 'auth';
  constructor(
    private http: HttpCall,
    private localStorageService: LocalStorageService,
    @Inject('localStorageKeys') private localStoragekeys: LocalStorageKeysModel
  ) {}

  login(loginData: LoginModel) {
    return this.http.post<HttpResponseModel>(
      FusionServers.BASE_API_SERVER,
      `${this.baseUrl}/login`,
      loginData
    );
  }

  signout() {
    return this.http.update<HttpResponseModel>(
      FusionServers.BASE_API_SERVER,
      `${this.baseUrl2}/logout`,{}
    );
  }

  verify(verifyOtpData: VerifyOtpModel) {
    return this.http.post<HttpResponseModel>(
      FusionServers.BASE_API_SERVER,
      `${this.baseUrl}/verify`,
      verifyOtpData
    );
  }
  changePassword(data:any){
     return this.http.update<HttpResponseModel>(
      FusionServers.BASE_API_SERVER,
      `adminController/userPW/updatePassword`,data
    );
  }

  /** an observable to check if user logged in or not */
  isUserLoggedIn(): Observable<boolean> {
    return this.isLoggedIn.asObservable();
  }

  /** @description used to set user logged in or logged out */
  setUserLoggedIn(state: boolean) {
    this.isLoggedIn.next(state);
  }

  /** @description get session detail from session storage */
  getSession() {
    const sessionData = this.localStorageService.getSessionStorage(
      this.localStoragekeys.APP_TOKEN_SESSION as string
    );
    return sessionData;
  }

  /** get current user mac address in login page */
  getMacIp() {
    return lastValueFrom<any>(
      this.http.getAll<any>(FusionServers.NODE_API_SERVER, `getuserMacIp`)
    );
  }

  getSelectedRole() {
    let seletedRole = this.localStorageService.getSessionStorage(
      this.localStoragekeys.APP_USER_SELECTED_ROLE as string
    );
    this.setSelectedRole(seletedRole);
    return this.selectedRole.asObservable();
  }

  setSelectedRole(role: any) {
    this.selectedRole.next(role);
  }

  /**
   * @description check if token is expired or not
   * */
  isTokenExpired() {
    let session = this.getSession();
    if (session) {
      return this.jwtHelper.isTokenExpired(session.token);
    }
    return false;
  }

  getProfileData(userNo: any) {
    return this.http.getAll<HttpResponseModel>(
      FusionServers.BASE_API_SERVER,
      `adminController/users/employee/${userNo}`
    );
  }
}
