import {
  Component,
  Inject,
  Injector,
  Input,
  OnChanges,
  OnInit,
  SimpleChanges,
  ViewEncapsulation,
} from '@angular/core';
import { FusionBase } from '@microSharedLib/core/models/classes/FusionBase';
import { LocalStorageKeysModel } from '@microSharedLib/core/models/interfaace/LocalStorageKeysModel.interface';
import { UntilDestroy, untilDestroyed } from '@ngneat/until-destroy';

@Component({
  selector: 'app-error-messages-container',
  templateUrl: './error-messages-container.component.html',
  styleUrls: ['./error-messages-container.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
@UntilDestroy({ checkProperties: true })
export class ErrorMessagesContainerComponent
  extends FusionBase
  implements OnInit, OnChanges
{
  @Input('validationErrorList') validationErrorList: string[] = [];

  currentLanguage: string = '';

  constructor(
    injector: Injector,
    @Inject('localStorageKeys') public localStorage: LocalStorageKeysModel
  ) {
    super(injector);
  }

  ngOnInit() {
    this.getAppLanguage();
  }

  ngOnChanges(changes: SimpleChanges): void {}

  getAppLanguage(): void {
    this.currentLanguage = this.getFusionHelper().getActiveLanguage(
      this.getLocalStorage().getLocal(this.localStorage.APP_LANG as string)
    );
    this.getTranslation()
      .onLangChange.pipe(untilDestroyed(this))
      .subscribe((lang) => {
        this.currentLanguage = lang?.lang;
      });
  }
}
