import { Inject, Injectable } from '@angular/core';
import {
  ActivatedRouteSnapshot,
  CanActivate,
  Router,
  RouterStateSnapshot,
  UrlTree,
} from '@angular/router';
import { Observable } from 'rxjs';
import { LocalStorageService } from '../helpers/LocalStorage.service';
import { LocalStorageKeysModel } from '../models/interfaace/LocalStorageKeysModel.interface';

@Injectable({
  providedIn: 'root',
})
export class CanActivateGuard implements CanActivate {
  constructor(
    @Inject('localStorageKeys') public localStorage: LocalStorageKeysModel,
    private localStorageService: LocalStorageService,
    private router: Router
  ) {}

  canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot) {
    const getToken = this.localStorageService.getSessionStorage(
      this.localStorage.APP_TOKEN_SESSION as string
    );
    if (getToken) {
      return true;
    }
    this.router.navigate(['/auth/login']);
    return false;
  }
}
