import { Injectable } from '@angular/core';
import {
  HttpEvent,
  HttpInterceptor,
  HttpHandler,
  HttpRequest,
  HttpResponse,
  HttpErrorResponse,
} from '@angular/common/http';
import { Observable, throwError } from 'rxjs';
import { catchError, map, tap } from 'rxjs/operators';
import { ToasterService } from '@microSharedLib/core/helpers/Toaster.service';
import { FusionBase } from '@microSharedLib/core/models/classes/FusionBase';
import { LocalStorageKeys } from '@fusionCore/models/enum/LocalStorageKeys.enum';
import { FusionbHelperService } from '@microSharedLib/core/helpers/FusionHelper.service';

@Injectable()
export class MessageInterceptor implements HttpInterceptor {
  currentLanguage!: any;
  constructor(
    private notificationService: ToasterService,
    private AppHelperService: FusionbHelperService
  ) {}

  intercept(req: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
    this.currentLanguage = this.AppHelperService.getActiveLanguage(
      LocalStorageKeys.APP_LANG
    );
    return next.handle(req).pipe(
      tap((event: HttpEvent<any>) => {
        if (event instanceof HttpResponse) {
          this.handleSuccessResponse(event);
        }
      }),
      catchError((error: HttpErrorResponse) => {
        this.handleErrorResponse(error);
        return throwError(error);
      })
    );
  }

  private handleSuccessResponse(event: HttpResponse<any>) {
    // Handle successful responses
    if (event.body && event.body.messages && event.body.messages.length) {
      this.notificationService.showToastSuccess(
        '',
        this.currentLanguage === 'ar' ? event.body.messages[0] : event.body.messages[1]
      );
    }
    if (event.body && event.body.errors && event.body.errors.length) {
      event.body.errors.forEach((err: any) => {
        this.notificationService.showToastError('', err.msg);
      });
    }
  }

  private handleErrorResponse(error: any) {
    // Handle error responses
    if (error.errors && error.errors.length) {
      error.errors.forEach((err: any) => {
        this.notificationService.showToastError('', err.msg);
      });
    } else {
       if (error.url.includes('/login') && error.status === 307) {}
       else{
      this.notificationService.showToastError('', 'An unknown error occurred.');
       }
    }
  }
}
