import {
  HttpEvent,
  HttpHandler,
  HttpInterceptor,
  HttpRequest,
} from '@angular/common/http';
import { Inject, Injectable } from '@angular/core';
import { Router } from '@angular/router';
import { Observable } from 'rxjs';
import { LocalStorageService } from '../helpers/LocalStorage.service';
import { FusionHeaderKeys } from '../models/enum/FusionHeaderKeys.enum';
import { LoginResponseModel } from '../models/interfaace/AppAuthEntity.interface';
import { LocalStorageKeysModel } from '../models/interfaace/LocalStorageKeysModel.interface';
import * as moment from 'moment';

@Injectable({
  providedIn: 'root',
})
export class HeaderKeysService implements HttpInterceptor {
  constructor(
    @Inject('localStorageKeys') public localStorage: LocalStorageKeysModel,
    private localStorageService: LocalStorageService,
    private router: Router
  ) {}

  intercept(req: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
    const currentLang =
      this.localStorageService.getLocal(this.localStorage.APP_LANG as string) ?? 'ar';
    const userSession: LoginResponseModel = this.localStorageService.getSessionStorage(
      this.localStorage.APP_TOKEN_SESSION as string
    );
    const selecetedRole = this.localStorageService.getSessionStorage(
      this.localStorage.APP_USER_SELECTED_ROLE as string
    );
    if (currentLang) {
      let request = req.clone({
        headers: req.headers
          .append(
            FusionHeaderKeys.HEADER_CURRENT_MC_CODE,
            userSession && userSession.mcCode ? String(userSession?.mcCode) : String(1)
          )
          .append(
            FusionHeaderKeys.HEADER_CURRENT_LANGUAGE,
            String(currentLang).toUpperCase()
          )
          .append(
            FusionHeaderKeys.HEADER_CURRENT_AUTHORIZATION,
            userSession?.token ? `Bearer ${userSession?.token as string}` : 'null'
          )
          .append(
            FusionHeaderKeys.HEADER_CURRENT_ROLE,
            selecetedRole ? `${selecetedRole as string}` : 'null'
          ),
      });

      //fromat all {Dates} inside payload object -- ♥ TarikElnaggar ♥ --
      if (request.body) {
        let req = request.body;
        for (const key in req) {
          if (req[key] instanceof Date) {
            req[key] = moment(req[key]).format('DD/MM/YYYY');
          }
        }
      }

      return next.handle(request);
    }

    return next.handle(req);
  }
}
