import { Component, Injector, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { SharedFusionModule } from '@microSharedLib/shared/SharedFusion.module';
import { UntilDestroy, untilDestroyed } from '@ngneat/until-destroy';
import { NgxSpinnerService } from 'ngx-spinner';
import { FusionBase } from '@microSharedLib/core/models/classes/FusionBase';
import { LocalStorageKeys } from '@fusionCore/models/enum/LocalStorageKeys.enum';

@Component({
  selector: 'micro-finance-header-notification',
  standalone: true,
  imports: [CommonModule, SharedFusionModule],
  templateUrl: './header-notification.component.html',
  styleUrls: ['./header-notification.component.scss'],
  providers: [NgxSpinnerService],
})
@UntilDestroy({ checkProperties: true })
export class HeaderNotificationComponent extends FusionBase implements OnInit {
  currentLanguage: string = '';
  constructor(injector: Injector) {
    super(injector);
    this.messageTranslationPrefix = '';
  }

  ngOnInit(): void {
    this.getAppLanguage();
    this.getSpinnerService().show('header-notification-spinner');
    setTimeout(() => {
      this.getSpinnerService().hide('header-notification-spinner');
    }, 5000);
  }

  override getAppLanguage(): void {
    this.currentLanguage = this.getFusionHelper().getActiveLanguage(
      LocalStorageKeys.APP_LANG
    );
    this.getTranslation()
      .onLangChange.pipe(untilDestroyed(this))
      .subscribe((lang) => {
        this.currentLanguage = lang?.lang;
      });
  }
}
