import { Component, Injector, Input, OnInit } from '@angular/core';
import { LocalStorageKeys } from '@fusionCore/models/enum/LocalStorageKeys.enum';
import { FusionBase } from '@microSharedLib/core/models/classes/FusionBase';
import { UntilDestroy, untilDestroyed } from '@ngneat/until-destroy';
import { interval, takeWhile } from 'rxjs';
import { EndOfDayService } from '@microSharedLib/services/end-of-day.service';
import { AuthService } from '@microSharedLib/services/auth.service';
import { FormGroup, Validators, UntypedFormArray, FormControl } from '@angular/forms';
import { LoginResponseModel } from '@microSharedLib/core/models/interfaace/AppAuthEntity.interface';
import { ApplicationLookupsService } from '@microSharedLib/services/application-lookups.service';
import { FinanceService } from '@microSharedLib/services/finance.service';
import {
  basicUiControlsModel,
  basicUiFunctionModel,
  basicUiLookupModel,
} from './basic-ui.model';

@Component({
  selector: 'micro-finance-basic-ui',
  templateUrl: './basic-ui.component.html',
  styleUrls: ['./basic-ui.component.scss'],
})
@UntilDestroy({ checkProperties: true })
export class BasicUiComponent extends FusionBase implements OnInit {
  currentLanguage: string = '';
  isEditMode: 'INSERT' | 'UPDATE' = 'INSERT';
  userSession!: LoginResponseModel;
  @Input() formInstance!: FormGroup;
  @Input() controlsArray!: basicUiControlsModel[];
  @Input() lookupsArray!: basicUiLookupModel;
  @Input() functionsObj!: basicUiFunctionModel;
  @Input() messageTranslation!: string;

  constructor(injector: Injector) {
    super(injector);
  }

  ngOnInit(): void {
    this.userSession = this.localStorageService.getSessionStorage(
      LocalStorageKeys.APP_TOKEN_SESSION as string
    );
    this.getAppLanguage();
    this.messageTranslationPrefix = this.messageTranslation;
  }

  getAppLanguage(): void {
    this.currentLanguage = this.getFusionHelper().getActiveLanguage(
      LocalStorageKeys.APP_LANG
    );
    this.getTranslation()
      .onLangChange.pipe(untilDestroyed(this))
      .subscribe((lang) => {
        this.currentLanguage = lang?.lang;
      });
  }
}
