import {
  Component,
  Inject,
  Injector,
  Input,
  OnChanges,
  OnInit,
  SimpleChanges,
} from '@angular/core';
import { AbstractControl, FormArray, FormGroup, UntypedFormGroup } from '@angular/forms';
import { FusionBase } from '@microSharedLib/core/models/classes/FusionBase';
import { LocalStorageKeysModel } from '@microSharedLib/core/models/interfaace/LocalStorageKeysModel.interface';
import { UntilDestroy, untilDestroyed } from '@ngneat/until-destroy';

interface LengthValParam {
  default?: number;
  minLength?: number;
  maxLength?: number;
  val1?: number;
  val2?: number;
  length?: number;
}

@Component({
  selector: 'lib-form-validation-error',
  templateUrl: './form-validation-error.component.html',
  styleUrls: ['./form-validation-error.component.scss'],
})
@UntilDestroy({ checkProperties: true })
export class FormValidationErrorComponent
  extends FusionBase
  implements OnInit, OnChanges
{
  @Input() isArabicMode: boolean = false;
  @Input('validationErrorList') validationErrorList: string[] = [];
  @Input('formInstance') formInstance!: FormGroup | UntypedFormGroup;
  @Input('formArrayInstance') formArrayInstance!: string;
  @Input('formControlIndex') formControlIndex!: number;
  @Input('controlName') controlName: string = '';
  @Input('controlNames') controlNames?: string[];
  @Input('lengthValParam') LengthValParam!: LengthValParam;
  @Input('translationPrefix') translationPrefix: any = null;

  currentLanguage: string = '';

  constructor(
    injector: Injector,
    @Inject('localStorageKeys') public localStorage: LocalStorageKeysModel
  ) {
    super(injector);
  }

  ngOnInit() {
    this.getAppLanguage();
  }

  ngOnChanges(changes: SimpleChanges): void {
    // Handle changes if needed
  }

  getAppLanguage(): void {
    this.currentLanguage = this.getFusionHelper().getActiveLanguage(
      this.localStorage.APP_LANG as string
    );
    this.getTranslation()
      .onLangChange.pipe(untilDestroyed(this))
      .subscribe((lang) => {
        this.currentLanguage = lang?.lang;
      });
  }

  getFormArray() {
    return this.formInstance.get(this.formArrayInstance) as FormArray;
  }

  getControl(path: string): AbstractControl | null {
    return this.formInstance.get(path);
  }

  hasErrors(): boolean {
    if (this.controlNames) {
      return this.controlNames.some((controlName) => {
        const control = this.getControl(controlName);
        return control?.errors && control.touched;
      });
    } else if (this.controlName) {
      const control = this.getControl(this.controlName);
      return !!(control?.errors && control.touched);
    }
    return false;
  }
  controlNameInfected(): string {
    if (this.controlNames) {
      let name: string = '';
      this.controlNames.some((controlName) => {
        const control = this.getControl(controlName);
        control?.errors && control.touched ? (name = controlName) : '';
        return;
      });
      return name;
    }
    return '';
  }

  getErrors(): { [key: string]: any } | null {
    if (this.controlNames) {
      const allErrors: { [key: string]: any } = {};

      this.controlNames.forEach((controlName) => {
        const control = this.getControl(controlName);
        if (control?.errors && control.touched) {
          Object.assign(allErrors, control.errors);
        }
      });

      return Object.keys(allErrors).length > 0 ? allErrors : null;
    } else if (this.controlName) {
      const control = this.getControl(this.controlName);
      return control?.touched ? control.errors : null;
    }
    return null;
  }
}
