import { Inject, Injectable } from '@angular/core';
import { environment } from '@fusionEnv/environment';
/**
 * @description uage of this class
 * 1- user can create any number of servers he used to get data from
 * 2- user can use [serverWithApiUrl] method to call the full server or can create his own url with multiple prifixes
 */
@Injectable({
  providedIn: 'root',
})
export class HttpConfigService {
  servers = {
    baseServer: {
      baseUrl: `${environment.appsUrl.baseUrl}/fmc/`,
    },
    nodeServer: {
      baseUrl: `${environment.appsUrl.nodeUrl}/`,
    },
  };

  constructor() {} // @Inject('env') private env:any
}
