import {
  Router,
  RouterModule,
  Event,
  NavigationStart,
  NavigationEnd,
  NavigationError,
} from '@angular/router';

import { NgModule } from '@angular/core';
import { AppLayoutComponent } from './layout/app.layout.component';
import { NotfoundComponent } from '@fusionPages/ErrorPages/notfound/notfound.component';
import { CanActivateGuard } from '@microSharedLib/core/security/can-activate.guard';
import { CanMatchGuard } from '@microSharedLib/core/security/can-match.guard';
import { NavigationPaths } from '@fusionCore/routes/NavigationPaths.enum';
import { LayoutService } from '@fusionLayout/service/app.layout.service';
import {RoleGuard}from '@microSharedLib/core/security/roles.guard';
@NgModule({
  imports: [
    RouterModule.forRoot(
      [
        {
          path: '',
          redirectTo: NavigationPaths.NAVIGATE_TO_DASHBOARD,
          pathMatch: 'full',
        },
        {
          path: NavigationPaths.NAVIGATE_TO_AUTH,
          loadComponent: () =>
            import(
              './layout/module-layouts/auth-main-layout/auth-main-layout.component'
            ).then((m) => m.AuthMainLayoutComponent),
          loadChildren: () =>
            import('./pages/auth/auth.module').then((m) => m.AuthModule),
        },
        {
          path: '',
          component: AppLayoutComponent,
          children: [
            {
              path: NavigationPaths.NAVIGATE_TO_DASHBOARD,
              loadChildren: () =>
                import('./pages/dashboard/dashboard.module').then(
                  (m) => m.DashboardModule
                ),
              canActivate: [CanActivateGuard,RoleGuard],
              canMatch: [CanMatchGuard],
            },
            {
              path: NavigationPaths.NAVIGATE_TO_HOME,
              loadChildren: () =>
                import('./pages/home/home.module').then((m) => m.HomeModule),
              canActivate: [CanActivateGuard],
              canMatch: [CanMatchGuard],
            },
          ],
        },
        {
          path: NavigationPaths.NAVIGATE_TO_LOOKUPS,
          component: AppLayoutComponent,
          loadChildren: () =>
            import('./pages/lookups/lookups.module').then((m) => m.LookupsModule),
          canActivate: [CanActivateGuard],
          canMatch: [CanMatchGuard],
        },
        {
          path: NavigationPaths.NAVIGATE_TO_ADMIN,
          component: AppLayoutComponent,
          loadChildren: () =>
            import('./pages/admin/admin.module').then((m) => m.AdminModule),
          canActivate: [CanActivateGuard],
          canMatch: [CanMatchGuard],
        },
        {
          path: NavigationPaths.NAVIGATE_TO_OVERSIGHT_REVIEW,
          component: AppLayoutComponent,
          loadChildren: () =>
            import('./pages/oversight-review/oversight-review.module').then(
              (m) => m.OversightReviewModule
            ),
          canActivate: [CanActivateGuard],
          canMatch: [CanMatchGuard],
        },
        {
          path: NavigationPaths.NAVIGATE_TO_BLACK_LIST,
          component: AppLayoutComponent,
          loadChildren: () =>
            import('./pages/black-list/black-list.module').then((m) => m.BlackListModule),
          canActivate: [CanActivateGuard],
          canMatch: [CanMatchGuard],
        },
        {
          path: NavigationPaths.NAVIGATE_TO_REPORTS,
          component: AppLayoutComponent,
          loadChildren: () =>
            import('./pages/reports/reports.module').then((m) => m.ReportsModule),
          canActivate: [CanActivateGuard],
          canMatch: [CanMatchGuard],
        },
        {
          path: NavigationPaths.NAVIGATE_TO_FINANCIAL,
          component: AppLayoutComponent,
          loadChildren: () =>
            import('./pages/financial-gl/financial-gl.module').then(
              (m) => m.FinancialGlModule
            ),
          canActivate: [CanActivateGuard],
          canMatch: [CanMatchGuard],
        },
        {
          path: NavigationPaths.NAVIGATE_TO_FINANCIAL_POLICIES,
          component: AppLayoutComponent,
          loadChildren: () =>
            import('./pages/financial-policies/financial-policies.module').then(
              (m) => m.FinancialPoliciesModule
            ),
          canActivate: [CanActivateGuard],
          canMatch: [CanMatchGuard],
        },
        {
          path: NavigationPaths.NAVIGATE_TO_COLLECTION,
          component: AppLayoutComponent,
          loadChildren: () =>
            import('./pages/collection-follow/collection-follow.module').then(
              (m) => m.CollectionFollowModule
            ),
          canActivate: [CanActivateGuard],
          canMatch: [CanMatchGuard],
        },
        {
          path: NavigationPaths.NAVIGATE_TO_FUNDING_REQUESTS,
          component: AppLayoutComponent,
          loadChildren: () =>
            import('./pages/funding-request/funding-request.module').then(
              (m) => m.FundingRequestModule
            ),
          canActivate: [CanActivateGuard],
          canMatch: [CanMatchGuard],
        },
        {
          path: NavigationPaths.NAVIGATE_TO_FUNDING_PROGRAM_SERVICE,
          component: AppLayoutComponent,
          loadChildren: () =>
            import(
              './pages/funding-prog-service-transactions/funding-prog-service-transactions.module'
            ).then((m) => m.FundingProgServiceModule),
          canActivate: [CanActivateGuard],
          canMatch: [CanMatchGuard],
        },
        {
          path: NavigationPaths.NAVIGATE_TO_FUNDING_PROGRAMS,
          component: AppLayoutComponent,
          loadChildren: () =>
            import('./pages/funding-programs/funding-programs.module').then(
              (m) => m.FundingProgramsModule
            ),
          canActivate: [CanActivateGuard],
          canMatch: [CanMatchGuard],
        },
        {
          path: NavigationPaths.NAVIGATE_TO_RIGHT_ASSIGNMENT,
          component: AppLayoutComponent,
          loadChildren: () =>
            import('./pages/right-assignment/right-assignment.module').then(
              (m) => m.RightAssignmentModule
            ),
          canActivate: [CanActivateGuard],
          canMatch: [CanMatchGuard],
        },
        {
          path: NavigationPaths.NAVIGATE_TO_WRITE_OFF,
          component: AppLayoutComponent,
          loadChildren: () =>
            import('./pages/write-off/write-off.module').then((m) => m.WriteOffModule),
          canActivate: [CanActivateGuard],
          canMatch: [CanMatchGuard],
        },
        {
          path: NavigationPaths.NAVIGATE_TO_END_OF_DAY,
          component: AppLayoutComponent,
          loadChildren: () =>
            import('./pages/end-of-day/end-of-day.module').then((m) => m.EndOfDayModule),
          canActivate: [CanActivateGuard],
          canMatch: [CanMatchGuard],
        },
        {
          path: NavigationPaths.NAVIGATE_TO_BRANCH_RM,
          component: AppLayoutComponent,
          loadChildren: () =>
            import('./pages/branches-requests/branches-requests.module').then(
              (m) => m.BranchRmModule
            ),
          canActivate: [CanActivateGuard],
          canMatch: [CanMatchGuard],
        },
        {
          path: NavigationPaths.NAVIGATE_TO_INCENTIVES,
          component: AppLayoutComponent,
          loadChildren: () =>
            import('./pages/incentives/incentives.module').then(
              (m) => m.IncentivesModule
            ),
          canActivate: [CanActivateGuard],
          canMatch: [CanMatchGuard],
        },
        {
          path: NavigationPaths.NAVIGATE_TO_RECONCLIE,
          component: AppLayoutComponent,
          loadChildren: () =>
            import('./pages/reconcile/reconcile.module').then((m) => m.ReconcileModule),
          canActivate: [CanActivateGuard],
          canMatch: [CanMatchGuard],
        },
        {
          path: NavigationPaths.NAVIGATE_TO_EXPENSES_REVENUE,
          component: AppLayoutComponent,
          loadChildren: () =>
            import('./pages/expenses-revenue/expenses-revenue.module').then(
              (m) => m.ExpensesRevenueModule
            ),
          canActivate: [CanActivateGuard],
          canMatch: [CanMatchGuard],
        },
        {
          path: NavigationPaths.NAVIGATE_TO_BOOKS,
          component: AppLayoutComponent,
          loadChildren: () =>
            import('./pages/books/books.module').then((m) => m.BooksModule),
          canActivate: [CanActivateGuard],
          canMatch: [CanMatchGuard],
        },
        {
          path: NavigationPaths.NAVIGATE_TO_RESCUDULE,
          component: AppLayoutComponent,
          loadChildren: () =>
            import('./pages/funding-reschedule/funding-reschedule.module').then((m) => m.FundingRescheduleModule),
          canActivate: [CanActivateGuard],
          canMatch: [CanMatchGuard],
        },
                {
          path: NavigationPaths.NAVIGATE_TO_FINANCIAL,
          component: AppLayoutComponent,
          loadChildren: () =>
            import('./pages/financial-gl/financial-gl.module').then(
              (m) => m.FinancialGlModule
            ),
          canActivate: [CanActivateGuard],
          canMatch: [CanMatchGuard],
        },
        { path: 'pages/server-error', component: NotfoundComponent },
        { path: 'pages/notfound', component: NotfoundComponent },
        { path: '**', redirectTo: 'pages/notfound' },
      ],
      {
        scrollPositionRestoration: 'enabled',
        anchorScrolling: 'enabled',
        onSameUrlNavigation: 'reload',
        urlUpdateStrategy: 'eager',
        useHash: true,
      }
    ),
  ],
  exports: [RouterModule],
})
export class AppRoutingModule {
  constructor(private router: Router, private layoutService: LayoutService) {
    this.router.events.subscribe((event: Event) => {
      if (event instanceof NavigationEnd) {
        // Show progress spinner or progress bar
        this.layoutService.state.staticMenuDesktopInactive = true;
      }
      if (event instanceof NavigationError) {
        // Hide progress spinner or progress bar
        this.layoutService.state.staticMenuDesktopInactive = true;
      }
    });
  }
}
